const translations = { en, de, fr, es, zh };
const languageNames = { ru: 'Русский', en: 'English', de: 'Deutsch', fr: 'Français', es: 'Español', zh: '中文' };
const localeByLanguage = { ru: 'ru-RU', en: 'en-US', de: 'de-DE', fr: 'fr-FR', es: 'es-ES', zh: 'zh-CN' };
const currencyByLanguage = { ru: 'RUB', en: 'USD', de: 'EUR', fr: 'EUR', es: 'EUR', zh: 'CNY' };
const currencyByRegion = {
  RU: 'RUB', BY: 'BYN', KZ: 'KZT', UA: 'UAH', US: 'USD', GB: 'GBP', CA: 'CAD', AU: 'AUD', NZ: 'NZD',
  CN: 'CNY', HK: 'HKD', TW: 'TWD', JP: 'JPY', IN: 'INR', BR: 'BRL', TR: 'TRY', AE: 'AED', SA: 'SAR',
  CH: 'CHF', SG: 'SGD', PL: 'PLN', CZ: 'CZK', SE: 'SEK', NO: 'NOK', DK: 'DKK',
  AT: 'EUR', BE: 'EUR', DE: 'EUR', ES: 'EUR', FR: 'EUR', IT: 'EUR', PT: 'EUR', NL: 'EUR', IE: 'EUR',
  FI: 'EUR', EE: 'EUR', LV: 'EUR', LT: 'EUR', SK: 'EUR', SI: 'EUR', GR: 'EUR', CY: 'EUR', MT: 'EUR', LU: 'EUR'
};
const fallbackRates = {
  RUB: 1, USD: 0.0124, EUR: 0.0107, GBP: 0.0094, CNY: 0.088, KZT: 5.65, UAH: 0.52, BYN: 0.042,
  BRL: 0.066, CAD: 0.0173, AUD: 0.019, NZD: 0.0215, HKD: 0.0965, TWD: 0.38, JPY: 1.9, INR: 1.1,
  TRY: 0.52, AED: 0.0455, SAR: 0.0465, CHF: 0.0099, SGD: 0.0161, PLN: 0.0452, CZK: 0.259, SEK: 0.117, NOK: 0.125, DKK: 0.0798
};
const originalTitle = document.title;
const originalMeta = document.querySelector('meta[name="description"]')?.content || '';
const originalText = new WeakMap();
const originalAttributes = new WeakMap();
let rates = { ...fallbackRates };
let currentLanguage = 'ru';
let currentLocale = 'ru-RU';
let currentCurrency = 'RUB';
let priceNote;

function browserLocale() {
  return (navigator.languages && navigator.languages[0]) || navigator.language || 'ru-RU';
}
function supportedLanguage(locale) {
  const base = String(locale).toLowerCase().split('-')[0];
  return languageNames[base] ? base : 'en';
}
function regionOf(locale) {
  try { return new Intl.Locale(locale).maximize().region || ''; } catch { return ''; }
}
function detectCurrency(locale, language) {
  const region = regionOf(locale);
  if (supportedLanguage(locale) === language && currencyByRegion[region]) return currencyByRegion[region];
  return currencyByLanguage[language] || currencyByRegion[region] || 'USD';
}
function money(value, currency = currentCurrency, approximate = false) {
  let formatted;
  try {
    formatted = new Intl.NumberFormat(currentLocale, { style: 'currency', currency, maximumFractionDigits: 0, minimumFractionDigits: 0 }).format(value);
  } catch {
    formatted = `${Math.round(value)} ${currency}`;
  }
  return approximate && currency !== 'RUB' ? `≈${formatted}` : formatted;
}
function zeroPrice() { return money(0); }
function supportPrice() { return money(3990 * (rates[currentCurrency] || fallbackRates.USD), currentCurrency, true); }
function basePrice() { return money(3990, 'RUB'); }
function t(key) {
  if (key === '0 ₽') return zeroPrice();
  if (key === '0 ₽.') return `${zeroPrice()}.`;
  const dictionary = translations[currentLanguage] || {};
  let value = currentLanguage === 'ru' ? key : (dictionary[key] || en[key] || key);
  if (currentLanguage === 'ru') value = value.replaceAll('0 ₽', '{zero}').replaceAll('3 990 ₽', '{supportPrice}');
  return value.replaceAll('{zero}', zeroPrice()).replaceAll('{supportPrice}', supportPrice()).replaceAll('{basePrice}', basePrice());
}
function translateText(raw) {
  const text = raw.trim();
  if (!text) return raw;
  return raw.replace(text, t(text));
}
function applyTranslations() {
  document.documentElement.lang = currentLanguage;
  document.title = t(originalTitle);
  const meta = document.querySelector('meta[name="description"]');
  if (meta) meta.content = t(originalMeta);
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  for (const node of nodes) {
    if (['SCRIPT', 'STYLE'].includes(node.parentElement?.tagName) || node.parentElement?.closest('.language-picker')) continue;
    if (!originalText.has(node)) originalText.set(node, node.nodeValue);
    node.nodeValue = translateText(originalText.get(node));
  }
  const elements = document.querySelectorAll('[aria-label], [placeholder], meta[name="description"]');
  for (const element of elements) {
    if (!originalAttributes.has(element)) originalAttributes.set(element, {});
    const originals = originalAttributes.get(element);
    for (const attribute of ['aria-label', 'placeholder', 'content']) {
      if (!element.hasAttribute(attribute)) continue;
      if (!(attribute in originals)) originals[attribute] = element.getAttribute(attribute);
      element.setAttribute(attribute, t(originals[attribute]));
    }
  }
  const picker = document.querySelector('#language-select');
  if (picker) picker.value = currentLanguage;
  if (priceNote) priceNote.hidden = currentCurrency === 'RUB';
  document.dispatchEvent(new CustomEvent('baiagent:languagechange', { detail: { language: currentLanguage, currency: currentCurrency } }));
}
function addControls() {
  const header = document.querySelector('.site-header');
  const label = document.createElement('label');
  label.className = 'language-picker';
  label.innerHTML = `<span class="sr-only">Язык страницы</span><select id="language-select" aria-label="Язык страницы">${Object.entries(languageNames).map(([code, name]) => `<option value="${code}" lang="${code}">${name}</option>`).join('')}</select>`;
  header.insertBefore(label, header.querySelector('.header-cta'));
  label.querySelector('select').addEventListener('change', event => {
    currentLanguage = event.target.value;
    currentLocale = localeByLanguage[currentLanguage] || currentLocale;
    currentCurrency = detectCurrency(currentLocale, currentLanguage);
    try { localStorage.setItem('baiagent-language', currentLanguage); } catch {}
    applyTranslations();
    loadRates();
  });
  priceNote = document.createElement('small');
  priceNote.className = 'support-price-note';
  priceNote.textContent = 'Ориентир по курсу; базовая цена — 3 990 ₽/мес';
  document.querySelector('.support-card > strong')?.insertAdjacentElement('afterend', priceNote);
}
function initialise() {
  let saved = null;
  try { saved = localStorage.getItem('baiagent-language'); } catch {}
  const detectedLocale = browserLocale();
  const detectedLanguage = supportedLanguage(detectedLocale);
  currentLanguage = saved && languageNames[saved] ? saved : detectedLanguage;
  currentLocale = currentLanguage === detectedLanguage ? detectedLocale : (localeByLanguage[currentLanguage] || detectedLocale);
  currentCurrency = detectCurrency(currentLocale, currentLanguage);
  addControls();
  applyTranslations();
  loadRates();
}
async function loadRates() {
  if (currentCurrency === 'RUB') return;
  try {
    const cached = JSON.parse(localStorage.getItem('baiagent-rates') || 'null');
    if (cached && Date.now() - cached.time < 12 * 60 * 60 * 1000 && cached.rates) rates = { ...fallbackRates, ...cached.rates };
  } catch {}
  applyTranslations();
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 4000);
  try {
    const response = await fetch('https://open.er-api.com/v6/latest/RUB', { signal: controller.signal });
    if (!response.ok) return;
    const data = await response.json();
    if (data.result !== 'success' || !data.rates) return;
    rates = { ...fallbackRates, ...data.rates };
    try { localStorage.setItem('baiagent-rates', JSON.stringify({ time: Date.now(), rates: data.rates })); } catch {}
    applyTranslations();
  } catch {
    // Embedded approximate rates keep the page usable without a third-party connection.
  } finally {
    clearTimeout(timer);
  }
}

window.baiagentI18n = { t, apply: applyTranslations, get language() { return currentLanguage; }, get currency() { return currentCurrency; } };
initialise();
